/*! Morphext - Smooth Version */

!function ($) {

    "use strict";

    function Morphext(element, options) {

        this.element = $(element);

        this.settings = $.extend({}, defaults, options);

        this._defaults = defaults;

        this._init();
    }

    var pluginName = "Morphext";

    var defaults = {

        animation: "fadeInUp",

        separator: ",",

        speed: 4000,

        complete: $.noop
    };

    Morphext.prototype = {

        _init: function () {

            var self = this;

            this.phrases = [];

            this.element.addClass("morphext");

            $.each(
                this.element.text().split(this.settings.separator),

                function (index, phrase) {

                    self.phrases.push($.trim(phrase));
                }
            );

            this.index = -1;

            this.animate();

            this.start();
        },

        animate: function () {

            this.index = ++this.index % this.phrases.length;

            this.element[0].innerHTML =
                '<span class="animated ' +
                this.settings.animation +
                '">' +
                this.phrases[this.index] +
                "</span>";

            if ($.isFunction(this.settings.complete)) {

                this.settings.complete.call(this);
            }
        },

        start: function () {

            var self = this;

            this._interval = setInterval(function () {

                self.animate();

            }, this.settings.speed);
        },

        stop: function () {

            this._interval = clearInterval(this._interval);
        }
    };

    $.fn[pluginName] = function (options) {

        return this.each(function () {

            if (!$.data(this, "plugin_" + pluginName)) {

                $.data(
                    this,
                    "plugin_" + pluginName,
                    new Morphext(this, options)
                );
            }
        });
    };

}(jQuery);